local _, WFJ = ...
WFJ.Data.add("book", {
  ["563b7ca9854f840c"] = { "Mentre viaggiavano in silenzio, osservarono i resti del loro mondo e capirono che erano state le loro passioni a causare la distruzione tutt'intorno. Benché Sargeras e la sua Legione fossero stati strappati dal mondo con la distruzione del Pozzo, a Malfurion e ai suoi compagni non restò che meditare sul terribile prezzo della vittoria.", "." },
  ["5643bd9de4d72bc0"] = { "Man mano che la sua padronanza del potere cosmico di Tirisfal cresceva, Aegwynn venne a sapere di alcuni potenti demoni che si aggiravano nel gelido continente settentrionale di Nordania. Recatasi nel lontano nord, Aegwynn seguì le tracce dei demoni fin sulle montagne. Lì scoprì che i demoni davano la caccia a uno degli ultimi stormi di draghi sopravvissuti e prosciugavano quelle antiche creature della loro magia innata.", "." },
  ["5683d7bbf73502c7"] = { "Verrò a incontrarvi di persona quando le piogge invernali si saranno placate e le strade saranno di nuovo percorribili.\n\nFino ad allora,\n\nStalvan Mistmantle di ⟦Silverpine=Pinargento⟧", "." },
  ["56b34777811242e7"] = { "Capitano,\n\nTi auguro fortuna nei tuoi viaggi. Purtroppo la fortuna non ha favorito il nostro primo tentativo di rapimento.\n\nQuando la nostra squadra ha raggiunto il bersaglio nei tunnel tra ⟦Stormwind=Roccavento⟧ e ⟦Ironforge=Forgiardente⟧, ha trovato solo un'esca. A quanto pare è stato più saggio di quanto gli riconoscessimo.\n\nMa il nostro secondo piano è già in moto. Gli agenti dei Defias sono pronti a intercettare il bersaglio mentre si avvicina a Theramore. Presto ⟦Stormwind=Roccavento⟧ sentirà fin troppo bene il nostro morso.\n\n-M", "." },
  ["56ffde288995359e"] = { "Ehi, amico. Porta 'sta lettera a Frang nella ⟦Valley of Trials=Valle delle Sfide⟧. Di solito sta fuori dall'Antro del Tirocinio a mettere in riga i giovani guerrieri, così combattono per l'⟦Horde=Orda⟧.\n\nGli servono guerrieri astuti come te, per mostrare agli orchi come si combatte con qualcosa che non sono i muscoli. Tu hai più velocità e più cervello della maggior parte di loro, ma non vantartene: gli orchi non la prendono bene, gli insulti. Sono buoni alleati, e magari pure loro t'insegnano una cosa o due.\n\n-Tar'sere", "." },
})
